+		err = -EINVAL;
+		f2fs_unlock_op(sbi, &lc);
+		f2fs_up_write_trace(&sbi->gc_lock, &glc);
+		goto out_inode_unlock;
+	}
+
+	filemap_invalidate_lock(inode->i_mapping);
+	truncate_setsize(inode, 0);
